// Label triangulation faces using odd-even rule propagation
// Start from the infinite face (exterior) and propagate through non-constrained edges
// When crossing a constrained edge, flip the interior/exterior status

Triangulation::Face_handle infinite_face = *triangulation.all_faces_begin();
std::queue<Triangulation::Face_handle> queue;

infinite_face->info().interior = false;
infinite_face->info().processed = true;
queue.push(infinite_face);

while (!queue.empty()) {
    Triangulation::Face_handle current = queue.front();
    queue.pop();

    // Check all 3 neighbors
    for (int i = 0; i < 3; i++) {
        Triangulation::Face_handle neighbor = current->neighbor(i);

        if (neighbor->info().processed) continue;

        // Get the edge between current and neighbor
        int edge_index = current->index(neighbor);

        // Check if this edge is constrained
        if (triangulation.is_constrained(Triangulation::Edge(current, i))) {
            // Crossing a constrained edge flips interior/exterior status
            neighbor->info().interior = !current->info().interior;
        } else {
            // Same status as current face
            neighbor->info().interior = current->info().interior;
        }

        neighbor->info().processed = true;
        queue.push(neighbor);
    }
}

